def check_solution(n):
    def tau(x):
        count = 0
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                count += 1
                if i*i != x:
                    count += 1
        return count

    return n == tau(n**12)

solutions = [1, 13, 25, 325]
for s in solutions:
    print(f"{s}: {check_solution(s)}")

import itertools

def solve():
    solutions = []
    # Try different numbers of prime factors k
    for k in range(1, 7):
        # Try different exponents a_i
        # We already know a_i < 4 is likely. Let's try 1-10 to be safe.
        for exponents in itertools.product(range(1, 11), repeat=k):
            n = 1
            for a in exponents:
                n *= (12 * a + 1)

            temp_n = n
            prime_factors = {}
            d = 2
            while d * d <= temp_n:
                while temp_n % d == 0:
                    prime_factors[d] = prime_factors.get(d, 0) + 1
                    temp_n //= d
                d += 1
            if temp_n > 1:
                prime_factors[temp_n] = prime_factors.get(temp_n, 0) + 1

            if sorted(list(prime_factors.values())) == sorted(list(exponents)):
                if len(prime_factors) == k:
                    solutions.append(n)
    return sorted(list(set(solutions)))

print(solve())
